 'WEB_DIRECT') AND s.os = 'Android' AND s.country = 'IND' -- GROUP BY 1,2,3,4,5,6,7,8,9 ), sl_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-02-14 18:30:00' AND __time < TIMESTAMP '2026-02-25 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), ui AS ( SELECT -- DISTINCT event_name event_name, CASE WHEN event_name = 'search information' THEN 'search information' ELSE event_value END AS event_value, usertype, screen_name, mri_session_id, mri_client_id FROM user_interaction.ui_ux_events u WHERE __time >= TIMESTAMP '2026-02-14 18:30:00' AND __time < TIMESTAMP '2026-02-25 18:30:00' AND header_bu = 'BUS' AND selected_country = 'India' AND event_src = 'Android' -- AND event_name NOT IN ('location widget') AND screen_name IN ('boarding point screen', 'dropping point screen', '') AND event_name IN ('location widget', 'location widget tapped', 'map location pop up viewed', 'location selection type', 'search information', 'user selection from', 'closest bp available', 'choice of bp from closest or normal', 'search information', 'user selection from', 'closest bp available', 'choice of bp from closest or normal', 'BP DP screen loaded') ), mpax_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-02-14 18:30:00' AND __time < TIMESTAMP '2026-02-25 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2 ), confirm_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id, SUM(tin_count) as tin_count FROM ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id, COUNT(DISTINCT tin) as tin_count FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-02-14 18:30:00' AND __time < TIMESTAMP '2026-02-25 18:30:00' AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2 ) GROUP BY 1,2 ) SELECT -- 'MTD Dec 28' AS month_period, -- srp.doi, srp.month_period || '15 to 25' AS month_period, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, -- UPPER(srp.user_type) as user_type, -- PAN INDIA Funnel COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT CASE WHEN u.event_name = 'BP DP screen loaded' THEN u.mri_session_id END) AS BP_Load, COUNT(DISTINCT CASE WHEN u.event_name = 'location widget' AND screen_name = 'boarding point screen' AND event_value = 'Yes' THEN u.mri_session_id END) AS bp_saw_location_widget, COUNT(DISTINCT CASE WHEN u.event_name = 'location widget tapped' AND screen_name = 'boarding point screen' AND event_value = 'map location' THEN u.mri_session_id END) AS BP_Selected_Current_Location, COUNT(DISTINCT CASE WHEN u.event_name = 'location selection type' AND screen_name = 'boarding point screen' AND event_value = 'precise' THEN u.mri_session_id END) AS BP_Used_location_permission, COUNT(DISTINCT CASE WHEN u.event_name = 'location widget tapped' AND screen_name = 'boarding point screen' AND event_value = 'search bar' THEN u.mri_session_id END) AS BP_Used_location_permission, COUNT(DISTINCT CASE WHEN u.event_name = 'location widget' AND screen_name = 'dropping point screen' AND event_value = 'Yes' THEN u.mri_session_id END) AS dp_saw_location_widget, COUNT(DISTINCT CASE WHEN u.event_name = 'location widget tapped' AND screen_name = 'dropping point screen' AND event_value = 'search bar' THEN u.mri_session_id END) AS DP_Used_location_permission, COUNT(DISTINCT pax.mri_session_id) AS paxload, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, COUNT(DISTINCT CASE WHEN u.event_name = 'location widget' AND screen_name = 'boarding point screen' AND event_value = 'Yes' THEN conf.mri_session_id END) AS bp_saw_location_widget_and_confirmed, COUNT(DISTINCT CASE WHEN u.event_name = 'location widget tapped' AND screen_name = 'boarding point screen' AND event_value = 'map location' THEN conf.mri_session_id END) AS BP_Selected_Current_Location_and_confirmed, COUNT(DISTINCT CASE WHEN u.event_name = 'location selection type' AND screen_name = 'boarding point screen' AND event_value = 'precise' THEN conf.mri_session_id END) AS BP_Used_location_permission_and_confirmed, COUNT(DISTINCT CASE WHEN u.event_name = 'location widget tapped' AND screen_name = 'boarding point screen' AND event_value = 'search bar' THEN conf.mri_session_id END) AS BP_Used_search_bar_and_confirmed, COUNT(DISTINCT CASE WHEN u.event_name = 'location widget' AND screen_name = 'dropping point screen' AND event_value = 'Yes' THEN conf.mri_session_id END) AS dp_saw_location_widget_and_confirmed, COUNT(DISTINCT CASE WHEN u.event_name = 'location widget tapped' AND screen_name = 'dropping point screen' AND event_value = 'search bar' THEN conf.mri_session_id END) AS DP_Used_search_bar_and_confirmed, SUM(conf.tin_count) AS tin FROM srp_deduped srp LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN ui u ON u.mri_session_id = sl.mri_session_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1, 2 -- , 3 ORDER BY 2, 3 DESC
